191: function CooldownSyncRelayMixin:GetSpellCooldown(spellID)
192: 	local cooldownInfo = C_Spell.GetSpellCooldown(spellID);
193: 	if not cooldownInfo then
194: 		return 0, 0, 1, -1;
195: 	end
196: 
197: 	local start = cooldownInfo.startTime;
198: 	local duration = cooldownInfo.duration;
199: 	local enabled = cooldownInfo.isEnabled;
200: 	local modRate = cooldownInfo.modRate or 1;
201: 
202: 	local chargeInfo = C_Spell.GetSpellCharges(spellID);
203: 	local currentCharges = chargeInfo and chargeInfo.currentCharges;
204: 	local maxCharges = chargeInfo and chargeInfo.maxCharges;
205: 	local chargeCooldownStart = chargeInfo and chargeInfo.cooldownStartTime;
206: 	local chargeCooldownDuration = chargeInfo and chargeInfo.cooldownDuration;
207: 	local chargeModRate = chargeInfo and chargeInfo.chargeModRate;
208: 	local charges = (maxCharges and maxCharges > 1) and currentCharges or -1;
209: 
210: 	if maxCharges and currentCharges and maxCharges > currentCharges then
211: 		return chargeCooldownStart, chargeCooldownDuration, chargeModRate or 1, charges;
212: 	end
213: 
214: 	if enabled then
215: 		if start and start > 0 then
216: 			if cooldownInfo.isOnGCD then
217: 				return nil;
218: 			end
219: 			return start, duration, modRate, charges;
220: 		end
221: 	end
222: 
223: 	return 0, 0, 1, charges;
224: end

